import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { leaveParentHandler } from "../handlers/leaveParentHandler";
import type { ApiError } from "../runtime/client";
import type { LeaveParentRequest } from "../types/LeaveParentRequest";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof leaveParentHandler>>;
type Vars = { teamPk: TeamPartition; body: LeaveParentRequest };

export function useLeaveParent(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => leaveParentHandler(vars.teamPk, vars.body),
    ...options,
  });
}
